-- A new tenant receives the category from the actual migration trigger. No
-- manual task.offer INSERT is allowed in this fixture before publication.
insert into app.tenants(id,slug,name)values('fc100000-0000-4000-8000-000000000001','owned-new-category-club','Owned fresh club');
select is((select count(*)from app.notification_categories where category_key='task.offer'),3::bigint,'all three newly created tenants get their own task offer category');
select is((select name from app.notification_categories where tenant_id='fc100000-0000-4000-8000-000000000001'and category_key='task.offer'),'Nieuw passend aanbod','new tenant receives actual canonical copy');
select ok((select not essential and version=1 from app.notification_categories where tenant_id='fc100000-0000-4000-8000-000000000001'and category_key='task.offer'),'news category is optional and starts at actual version one');
select is((select count(distinct id)from app.notification_categories where category_key='task.offer'),3::bigint,'category identities are tenant bound rather than shared');
select ok(not has_function_privilege('authenticated','internal.pwa_seed_task_offer_category()','EXECUTE'),'browser cannot invoke private seeding function');
select ok(not has_function_privilege('service_role','internal.pwa_seed_task_offer_category()','EXECUTE'),'service role cannot invoke private seeding function');
select ok(not has_function_privilege('cluvo_command_owner','internal.pwa_seed_task_offer_category()','EXECUTE'),'no new command owner seed RPC privilege');
select ok((select not p.prosecdef and pg_get_userbyid(p.proowner)='postgres' and p.proconfig=array['search_path=""'] from pg_proc p where p.oid='internal.pwa_seed_task_offer_category()'::regprocedure),'seed uses existing migration authority with empty search path and no definer escalation');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='app.notification_categories'::regclass),'notification category native forced RLS remains enabled');
update auth.users set email_confirmed_at=statement_timestamp();
insert into auth.sessions(id,user_id,created_at,updated_at)select id,id,statement_timestamp(),statement_timestamp()from auth.users;
create function pg_temp.actor(p_actor uuid)returns void language plpgsql security definer set search_path=''as $$begin
 perform set_config('request.jwt.claim.sub',p_actor::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',p_actor,'session_id',p_actor,'role','authenticated','email',(select email from auth.users where id=p_actor))::text,true);end;$$;
insert into app.notification_preferences(tenant_id,person_id,category_id,channel,enabled)
 select 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a1000000-0000-4000-8000-000000000001',id,'email',false from app.notification_categories where tenant_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'and category_key='task.offer';
insert into app.pwa_preferences(tenant_id,person_id,email,news)values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','a1000000-0000-4000-8000-000000000001',false,false);
create function pg_temp.public_payload()returns jsonb language sql set search_path=''as $$select '{"season_id":"a5000000-0000-4000-8000-000000000001","title":"Owned first club publication","starts_at":"2027-02-10T10:00:00+01:00","ends_at":"2027-02-10T12:00:00+01:00","task_type_version_id":"a9000000-0000-4000-8000-000000000001","capacity":2,"repeat_count":1,"instructions":"Concrete native first-publication instructions","minimum_age":16,"qualification_type_id":null,"min_qualified_count":0,"buddy_allowed":false,"distribution_mode":"public"}'::jsonb;$$;
set local role authenticated;select pg_temp.actor('11111111-1111-4111-8111-111111111111');
select is((select count(*)from app.notification_categories where tenant_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'and category_key='task.offer'),1::bigint,'current member reads actual own default category');
select is((select count(*)from app.notification_categories where tenant_id in('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','fc100000-0000-4000-8000-000000000001')),0::bigint,'member cannot read another club category');
select throws_ok($$insert into app.notification_categories(tenant_id,category_key,name)values('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','task.offer.other','Unauthorized')$$,'42501',null,'seed does not grant browser direct category INSERT');
select throws_ok($$insert into app.tenants(slug,name)values('unauthorized-native-tenant','Unauthorized')$$,'42501',null,'seed does not create a browser tenant creation route');
select throws_ok($$select api.pwa_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','create_club_task','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,pg_temp.public_payload(),'fc900000-0000-4000-8000-000000000001')$$,'42501','FORBIDDEN','category default never supplies missing planning authority');
select pg_temp.actor('33333333-3333-4333-8333-333333333333');
create temporary table publication as select resource_id,version,result from api.pwa_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','create_club_task','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,pg_temp.public_payload(),'fc900000-0000-4000-8000-000000000002');
select lives_ok($$select api.pwa_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','create_club_task','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,pg_temp.public_payload(),'fc900000-0000-4000-8000-000000000002')$$,'actual first publication succeeds and exact key replays without another shift');
select throws_ok($$select api.pwa_command('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','create_club_task','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',0,pg_temp.public_payload(),'fc900000-0000-4000-8000-000000000003')$$,'42501','FORBIDDEN','known default category cannot authorize cross-tenant publication');
reset role;
select is((select count(*)from app.shifts where title='Owned first club publication'),1::bigint,'first publication and replay preserve one actual shift');
select is((select state from app.shifts where id=(select resource_id from publication)),'published','canonical publication really changed shift state');
select is((select count(*)from app.shift_positions where shift_id=(select resource_id from publication)),2::bigint,'actual public shift has the requested two places');
select is((select minimum_age from app.shift_requirements where shift_id=(select resource_id from publication)),16,'publication preserves actual eligibility rules');
select is((select count(*)from app.pwa_instruction_versions where shift_id=(select resource_id from publication)and body='Concrete native first-publication instructions'),1::bigint,'publication has immutable actual preparation text');
select is((select count(*)from app.pwa_allocations a join app.shift_positions p on p.id=a.position_id where p.shift_id=(select resource_id from publication)),0::bigint,'public first task introduces no hidden reservation');
select ok((select not enabled from app.notification_preferences where tenant_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'and person_id='a1000000-0000-4000-8000-000000000001'and channel='email'),'registered category opt-out remains unchanged by publication');
select ok((select not email and not news from app.pwa_preferences where tenant_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'and person_id='a1000000-0000-4000-8000-000000000001'),'PWA optional email and news consent remain unchanged');
select is((select count(*)from app.notification_outbox where recipient_person_id='a1000000-0000-4000-8000-000000000001'and channel='email'),0::bigint,'canonical first-publication outbox respects existing email opt-out');
select is((select count(*)from app.hour_ledger_entries),1::bigint,'publishing a task does not award execution minutes');
select *from finish();rollback;
